function sharedCards(p,scope){
 const row=(key,label,value,percentValue=false,calculated=false)=>`<div class="shared-row"><label for="${scope}-${key}">${label}</label>${calculated?'<span class="hint">Calculated in results</span>':`<input id="${scope}-${key}" data-shared="${key}" ${percentValue?'type="number" step="any"':'type="text" inputmode="decimal" data-amount="true"'} value="${Number.isFinite(value)?percentValue?entry(value,100):formatAmount(value):''}">`}</div>`;
 const solving=scope==='riskfi';
 return `<div class="summary-grid shared-cards"><section class="summary-group"><h3>Starting numbers</h3>${row('portfolio','Investments ($)',p.portfolio,false,solving&&unknown==='portfolio')}${row('cash','Cash reserve ($)',cashAmount(p))}${row('fiWithdrawals','Annual withdrawals at FI ($)',p.fiWithdrawals)}${row('fiRate','FI withdrawal rate (%)',p.fiRate,true)}<div class="shared-row"><span>FI target · today’s dollars</span><strong>${money(fiTarget(p))}</strong></div></section><section class="summary-group"><h3>Assumptions</h3>${row('nominal','Return before inflation (%)',p.nominal,true,solving&&unknown==='return')}${row('inflation','Inflation (%)',p.inflation,true)}${row('cashNominal','Cash yield (%)',p.cashNominal,true)}${p.timeEntry==='age'?row('age','Current age',p.age):''}<p class="hint">${state.futureChanges.some(e=>e.enabled!==false)?state.futureChanges.filter(e=>e.enabled!==false).length+' future changes included. ':''}Shared with Your numbers. Aggregate asset edits preserve the allocation; return edits shift asset growth rates together.</p></section></div>`;
}
function bindSharedCards(scope,p){
 $$('#'+(scope==='riskfi'?'tool-setup':'view')+' [data-shared]').forEach(el=>{el.oninput=()=>{
 const key=el.dataset.shared,value=readNumber(el.value),isRate=['nominal','inflation','cashNominal','fiRate','withdrawalRate'].includes(key);
 // Materialize a calculated value only when the user explicitly edits it.
 if(key==='targetAge')state.years=yearsToAge(state.age,value);
 else state[key]=value===null?null:value/(isRate?100:1);
 if(key==='cash')state.cashMode='dollars';
 if(key==='spending')state.withdrawalMode='dollars';
 syncAssets(state);persist();rebuildInputs();
 };el.onblur=()=>update();});
}
function renderToolSetup(){
 const host=$('#tool-setup');host.hidden=tab!=='plan';if(tab!=='plan'){host.innerHTML='';return;}
 let solution;try{solution=unknown==='projection'?{plan:state}:solve(state,unknown);}catch{solution={plan:state};}const p=resolveWithdrawals(solution.plan||state);
 host.innerHTML=`<section class="panel content-panel"><h2>Risk Fi</h2><p><strong>Risk Fi:</strong> The point at which you have enough invested assets to begin funding some or all of your lifestyle from your portfolio <strong>before reaching traditional FI</strong>, because you retain the ability and willingness to <strong>reduce withdrawals or earn income if investment returns are unfavorable</strong>.</p><h3>Solve for</h3>${select('riskfi-solve','What would you like to find?',labels,unknown)}${sharedCards(p,'riskfi')}${riskfiSettings()}</section>`;
 $('#riskfi-solve').onchange=e=>{unknown=e.target.value;persist();rebuildInputs();update();};bindSharedCards('riskfi',p);bindRiskfiSettings();
}
function targetCaption(target,p,year){return `<p>FI target: <strong>${money(displayAmount(target,p,year))}</strong> ${nominal?'in future dollars at '+dateLabel(year):'in today’s dollars'}.</p>`;}
function renderGap(){
 const mode=gapSettings.mode||'time';
 const candidates=gapPeriods.map((p,i)=>({p,i})).filter(({p})=>p.action===mode);
 if(mode!=='time'&&!candidates.some(({i})=>i===gapSettings.index))gapSettings.index=candidates[0]?.i??-1;
 const p={...baselinePlan(state),...gapSettings,adjustWithdrawals:gapSettings.adjust};
 const amounts=(v,y=0)=>money(nominal?toNominal(v,p.inflation,y):v);
 $('#error').hidden=true;
 $('#view').innerHTML=`<section class="panel content-panel"><h2>Plan your path through different periods</h2><div class="field"><label>Solve for</label><div class="segmented">${[['time','When will I reach FI?'],['withdraw','Withdrawal amount'],['contribute','Contribution amount']].map(([v,l])=>`<button data-gap-solve="${v}" class="${mode===v?'active':''}" aria-pressed="${mode===v}">${l}</button>`).join('')}</div></div>${mode!=='time'?`<div class="two-fields">${select('gap-solve-period','Period to calculate',Object.fromEntries(candidates.map(({i})=>[i,'Period '+(i+1)])),gapSettings.index)}${field('gap-deadline','FI deadline (years from now)',gapSettings.years,{min:1,max:100,step:1})}</div><p class="hint">Calculate one period’s amount. All other periods stay fixed.</p>`:''}<p>Choose what happens during each period. The last period continues until FI.</p>${sharedCards(p,'gap')}<p class="hint">GapFi uses the periods below instead of RiskFi withdrawals.</p></section>
 <section class="panel content-panel"><h2>Your periods</h2>${select('gap-adjust','Annual amounts',{'yes':'Increase with inflation','no':'Keep dollar amount fixed'},gapSettings.adjust?'yes':'no')}${select('gap-cash-strategy','Cash strategy',{reserve:'Reserve only',first:'Use cash first',downturn:'Use cash in downturns'},gapSettings.cashStrategy)}<p class="hint">Annual amounts start in today’s dollars.</p><div class="gap-periods">${gapPeriods.map((period,i)=>`<section class="input-group"><h3>Period ${i+1}</h3><div class="segmented">${[['withdraw','Withdraw'],['even','Break even'],['contribute','Contribute']].map(([v,l])=>`<button data-gap-action="${v}" data-index="${i}" aria-pressed="${period.action===v}" class="${period.action===v?'active':''}">${l}</button>`).join('')}</div>${period.action!=='even'?field('gap-amount-'+i,period.action==='withdraw'?'Annual withdrawals':'Annual contributions',period.amount,{prefix:'$',min:0,disabled:mode!=='time'&&i===gapSettings.index}):'<p>No withdrawals or contributions.</p>'}<div class="segmented"><button data-gap-duration="years" data-index="${i}" class="${period.years!==null?'active':''}">For a period</button><button data-gap-duration="until" data-index="${i}" ${i!==gapPeriods.length-1?'disabled':''} class="${period.years===null?'active':''}">Until FI</button></div>${period.years!==null?field('gap-years-'+i,'Number of years',period.years,{min:1,max:99,step:1}):'<p class="hint">Continues until your total assets reach your FI target.</p>'}${gapPeriods.length>1?`<button class="text-button" data-gap-remove="${i}">Remove period ${i+1}</button>`:''}</section>`).join('')}</div><button id="gap-add">Add period</button><p class="hint">${p.adjustWithdrawals!==false?'Withdrawals and contributions increase with inflation.':'Withdrawals and contributions stay fixed in future dollars.'} Contributions go into investments.</p></section><section id="gap-results"></section>`;
 bindSharedCards('gap',p);
 $$('[data-gap-solve]').forEach(b=>b.onclick=()=>{gapSettings.mode=b.dataset.gapSolve;persist();renderGap();});
 if($('#gap-solve-period'))$('#gap-solve-period').onchange=e=>{gapSettings.index=+e.target.value;persist();renderGap();};
 if($('#gap-deadline'))$('#gap-deadline').oninput=e=>{gapSettings.years=readNumber(e.target.value);persist();renderGapResults(p,amounts);};
 $('#gap-adjust').onchange=e=>{gapSettings.adjust=e.target.value==='yes';persist();renderGap();};
 $('#gap-cash-strategy').onchange=e=>{gapSettings.cashStrategy=e.target.value;persist();renderGap();};
 const changed=()=>{persist();renderGap();};
 $$('[data-gap-action]').forEach(b=>b.onclick=()=>{gapPeriods[+b.dataset.index].action=b.dataset.gapAction;changed();});
 $$('[data-gap-duration]').forEach(b=>b.onclick=()=>{gapPeriods[+b.dataset.index].years=b.dataset.gapDuration==='until'?null:2;changed();});
 $$('[data-gap-remove]').forEach(b=>b.onclick=()=>{gapPeriods.splice(+b.dataset.gapRemove,1);gapPeriods.at(-1).years=null;changed();});
 $('#gap-add').onclick=()=>{if(gapPeriods.at(-1).years===null)gapPeriods.at(-1).years=2;gapPeriods.push({action:'even',amount:0,years:null});changed();};
 gapPeriods.forEach((period,i)=>{for(const key of ['amount','years']){const el=$('#gap-'+key+'-'+i);if(el)el.oninput=()=>{period[key]=readNumber(el.value);persist();renderGapResults(p,amounts);};}});
 renderGapResults(p,amounts);
}
function renderGapResults(p,amounts){
 charts=[];
 try{
 const solved=gapSettings.mode&&gapSettings.mode!=='time'?solveGapAmount(p,gapPeriods,gapSettings):null;
 const result=solved?solved.projection:projectGap(p,gapPeriods),arrival=result.reached;
 const rows=result.rows.map(r=>({...r,total:nominal?toNominal(r.total,p.inflation,r.year):r.total,target:nominal?toNominal(r.target,p.inflation,r.year):r.target}));
 $('#gap-results').innerHTML=`<h2 class="result-divider">Your GapFi results</h2><section class="panel content-panel"><h2>${solved?money(solved.amount)+' annual '+(gapSettings.mode==='withdraw'?'withdrawals':'contributions')+' · Period '+(gapSettings.index+1):result.shortfall!==null?'Withdrawals cannot be fully funded':arrival===null?'FI is not reached within 100 years':arrival===0?'You have reached your FI target':`FI in ${num(arrival,2)} years · ${dateLabel(arrival)}${p.timeEntry==='age'?' · Age '+num(p.age+arrival,1):''}`}</h2><p>${solved?'Starting in today’s dollars. Holds your FI target at '+dateLabel(gapSettings.years)+', with all withdrawals funded.':result.shortfall!==null?'A withdrawal shortfall occurs in '+dateLabel(result.shortfall)+'. The projection stops there.':arrival===null?'These periods do not reach the target within the projection limit.':'Total assets include investments and cash. Arrival is checked monthly.'}</p><div class="segmented"><button data-gap-dollars="real" class="${!nominal?'active':''}">Today’s dollars</button><button data-gap-dollars="nominal" class="${nominal?'active':''}">Future dollars</button></div>${targetCaption(result.target,p,solved?gapSettings.years:arrival??result.rows.at(-1).year)}${chart('gap-assets',rows,[{key:'total',label:'Total assets',color:'var(--purple)'},{key:'target',label:'FI target',color:'var(--muted)',dash:true}],{marker:arrival,boundaries:result.boundaries})}<p class="hint">Dotted lines mark period changes. Constant returns; withdrawals and contributions occur monthly. This is a projection, not a probability of success. The last row may cover part of a year.</p></section><section class="panel content-panel"><h2>Year by year</h2><div class="table-scroll"><table><thead><tr><th>${p.timeEntry==='age'?'Age':'Year'}</th><th>Period</th><th>Withdrawals</th><th>Contributions</th><th>Total assets</th><th>FI target</th></tr></thead><tbody>${result.rows.map(r=>`<tr><td>${num(p.timeEntry==='age'?p.age+r.year:r.year,2)}</td><td>${r.year===0?'Start':r.period+1}</td><td>${nominal?money(r.nominalWithdrawals):money(r.withdrawals)}</td><td>${nominal?money(r.nominalContributions):money(r.contributions)}</td><td>${amounts(r.total,r.year)}</td><td>${amounts(r.target,r.year)}</td></tr>`).join('')}</tbody></table></div></section>`;
 $('#gap-results').querySelector('section').insertAdjacentHTML('afterend',planTimeline(p,gapPeriods.map(x=>({...x,label:{withdraw:'Withdraw',contribute:'Contribute',even:'Break even'}[x.action]})),result.rows.at(-1).year,result.reached)+fundingChart(p,result.rows,nominal));
 $$('[data-gap-dollars]').forEach(b=>b.onclick=()=>{nominal=b.dataset.gapDollars==='nominal';persist();renderGap();});drawCharts();
 }catch(error){$('#gap-results').innerHTML='<div class="panel content-panel" role="alert"></div>';$('#gap-results div').textContent=error.message;}
}

function riskfiSettings(){
 const p=state;
 return `<div class="summary-grid"><section class="summary-group"><h3>RiskFi withdrawals</h3>${select('risk-withdrawalMode','Withdrawals as',{dollars:'Annual dollars',starting:'Percentage of starting investments',annual:'Percentage of each year’s investments'},p.withdrawalMode)}${p.withdrawalMode==='dollars'?field('risk-spending','Annual withdrawals',entry(p.spending,1,2),{prefix:'$',min:0,disabled:unknown==='spending'}):field('risk-withdrawalRate','Withdrawal percentage',entry(p.withdrawalRate,100),{suffix:'%',min:0,max:100,disabled:unknown==='spending'})}${select('risk-adjustWithdrawals','Dollar withdrawals',{'yes':'Increase with inflation','no':'Keep dollar amount fixed'},p.adjustWithdrawals?'yes':'no')}${p.withdrawalMode==='annual'?'<p class="hint">Annual percentages follow investments; inflation adjustment applies after FI.</p>':''}</section><section class="summary-group"><h3>RiskFi timeline & cash</h3>${p.timeEntry==='age'?field('risk-targetAge','Target FI age',enteredAge(),{min:0,disabled:unknown==='time'}):field('risk-years','Years to FI',entry(p.years),{min:0,max:100,disabled:unknown==='time'})}${select('risk-cashStrategy','Cash strategy',{reserve:'Reserve only',first:'Use cash first',downturn:'Use cash in downturns'},p.cashStrategy)}${field('risk-cashMinimum','Minimum cash reserve',p.cashMinimum,{prefix:'$',min:0})}<p class="hint">These settings apply to RiskFi only.</p></section></div>`;
}
function bindRiskfiSettings(){
 $$('#tool-setup [id^="risk-"]').forEach(el=>{
 const set=()=>{const key=el.id.slice(5);if(key==='withdrawalMode'||key==='cashStrategy')state[key]=el.value;else if(key==='adjustWithdrawals')state[key]=el.value==='yes';else if(key==='targetAge')state.years=yearsToAge(state.age,readNumber(el.value));else{const value=readNumber(el.value);state[key]=value===null?null:value/(key==='withdrawalRate'?100:1);}persist();};
 if(el.tagName==='SELECT')el.onchange=()=>{set();update();};else{el.oninput=set;el.onblur=()=>update();}
 });
}
function renderTraditional(){
 const p={...baselinePlan(state),adjustWithdrawals:traditional.adjust};$('#error').hidden=true;
 $('#view').innerHTML=`<section class="panel content-panel"><h2>Build toward Traditional Fi</h2><p>Calculate when contributions reach your FI target.</p><div class="summary-grid"><section class="summary-group"><h3>Your question</h3>${select('traditional-mode','Solve for',{time:'When will I reach FI?',contribution:'Contributions needed by my target date'},traditional.mode)}${traditional.mode==='time'?field('traditional-contribution','Annual contributions',traditional.contribution,{prefix:'$',min:0}):field('traditional-years','Years to FI',traditional.years,{min:1,max:100,step:1})}${traditional.mode==='contribution'&&Number.isFinite(traditional.years)?`<p class="hint">${dateLabel(traditional.years)}${p.timeEntry==='age'?' · Age '+num(p.age+traditional.years):''}</p>`:''}</section><section class="summary-group"><h3>Contribution rule</h3>${select('traditional-adjust','Annual contributions',{'yes':'Increase with inflation','no':'Keep dollar amount fixed'},traditional.adjust?'yes':'no')}<p class="hint">Contributions enter investments monthly. Cash stays separate and earns its cash yield.</p></section></div>${sharedCards(p,'traditional')}</section><section id="traditional-results"></section>`;
 bindSharedCards('traditional',p);
 for(const key of ['mode','contribution','years','adjust']){
 const el=$('#traditional-'+key);if(!el)continue;
 const set=()=>{traditional[key]=key==='mode'?el.value:key==='adjust'?el.value==='yes':readNumber(el.value);persist();};
 if(el.tagName==='SELECT')el.onchange=()=>{set();renderTraditional();};else{el.oninput=()=>{set();traditionalResults(p);};el.onblur=()=>renderTraditional();}
 }
 traditionalResults(p);
}
function traditionalResults(p){
 charts=[];
 try{
 const calculated=traditional.mode==='contribution'?contributionNeeded(p,traditional):null;
 const result=calculated?.projection||traditionalProjection(p,{...traditional,years:100});
 const amount=calculated?.contribution??traditional.contribution,at=result.reached;
 const moneyAt=(value,year)=>money(nominal?toNominal(value,p.inflation,year):value);
 const rows=result.rows.map(row=>({...row,total:nominal?toNominal(row.total,p.inflation,row.year):row.total,target:nominal?toNominal(row.target,p.inflation,row.year):row.target}));
 $('#traditional-results').innerHTML=`<h2 class="result-divider">Your Traditional Fi results</h2><section class="panel content-panel"><h2>${calculated?money(amount)+' per year':at===null?'FI is not reached within 100 years':at===0?'Your assets already meet the FI target':'FI in '+num(at,2)+' years · '+dateLabel(at)+(p.timeEntry==='age'?' · Age '+num(p.age+at):'')}</h2>${calculated?`<p>${money(amount/12)} per month, starting in today’s dollars, to hold your FI target in ${dateLabel(traditional.years)}.</p>`:`<p>Annual contributions: ${money(amount)} in today’s dollars.</p>`}<div class="segmented"><button data-trad-dollar="real" class="${nominal?'':'active'}">Today’s dollars</button><button data-trad-dollar="nominal" class="${nominal?'active':''}">Future dollars</button></div>${targetCaption(result.target,p,calculated?traditional.years:at??result.rows.at(-1).year)}${chart('traditional-assets',rows,[{key:'total',label:'Total assets',color:'var(--purple)'},{key:'target',label:'FI target',color:'var(--muted)',dash:true}],{marker:at})}<p class="hint">Constant returns; monthly contributions at month end. No withdrawals before FI. This is a projection, not a probability of success.</p></section><section class="panel content-panel"><h2>Year by year</h2><div class="table-scroll"><table><thead><tr><th>${p.timeEntry==='age'?'Age':'Year'}</th><th>Contributions</th><th>Investments</th><th>Cash</th><th>Total assets</th><th>FI target</th></tr></thead><tbody>${result.rows.map(r=>`<tr><td>${num(p.timeEntry==='age'?p.age+r.year:r.year,2)}</td><td>${money(nominal?r.nominalContributions:r.contributions)}</td><td>${moneyAt(r.investment,r.year)}</td><td>${moneyAt(r.cash,r.year)}</td><td>${moneyAt(r.total,r.year)}</td><td>${moneyAt(r.target,r.year)}</td></tr>`).join('')}</tbody></table></div></section>`;
 $('#traditional-results').querySelector('section').insertAdjacentHTML('afterend',planTimeline(p,[{action:'contribute',label:'Contribute',years:null}],result.rows.at(-1).year,result.reached)+fundingChart(p,result.rows,nominal));
 $$('[data-trad-dollar]').forEach(b=>b.onclick=()=>{nominal=b.dataset.tradDollar==='nominal';persist();traditionalResults(p);});drawCharts();
 }catch(e){$('#traditional-results').innerHTML='<div class="panel content-panel" role="alert"></div>';$('#traditional-results div').textContent=e.message;}
}

function safeText(v){return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function assetEditor(){return `<div class="asset-editor">${state.assets.map((a,i)=>`<section class="asset-row">${select('asset-type-'+i,'Asset type',{stocks:'Stocks',bonds:'Bonds',cash:'Cash'},a.type)}${field('asset-name-'+i,'Name',safeText(a.name),{type:'text'})}${field('asset-amount-'+i,'Amount',a.amount,{prefix:'$',min:0})}${field('asset-rate-'+i,'Expected return',entry(a.rate,100),{suffix:'%'})}<button data-remove-asset="${i}" class="text-button" ${state.assets.length===1?'disabled':''}>Remove asset</button></section>`).join('')}</div>`;}
function futureEditor(){return `<div class="future-editor">${state.futureChanges.map((e,i)=>`<section class="input-group"><div class="section-head"><h4 id="future-heading-${i}">${safeText(e.name?.trim()||({income:'Recurring income',add:'One-time addition',expense:'One-time expense'}[e.kind]))}</h4><label><input type="checkbox" id="future-enabled-${i}" ${e.enabled!==false?'checked':''}> Include</label></div>${select('future-kind-'+i,'Type',{income:'Recurring income',add:'One-time addition',expense:'One-time expense'},e.kind)}${field('future-name-'+i,'Name',safeText(e.name),{type:'text'})}${field('future-amount-'+i,e.kind==='income'?'Annual amount':'Amount',e.amount,{prefix:'$',min:0})}<div class="two-fields">${field('future-start-'+i,state.timeEntry==='age'?'Starting age':'Starts in years',e.start+(state.timeEntry==='age'?state.age:0),{min:0})}${e.kind==='income'?field('future-end-'+i,state.timeEntry==='age'?'Ending age (optional)':'Ends in years (optional)',e.end==null?'':e.end+(state.timeEntry==='age'?state.age:0),{min:0}):''}</div>${select('future-adjust-'+i,'Dollar amounts',{yes:'Keep purchasing power (rise with inflation)',no:'Fixed future-dollar payments'},e.adjust!==false?'yes':'no')}<button data-remove-future="${i}" class="text-button">Remove change</button></section>`).join('')}</div>`;}
function bindPlanningEditors(){
 const refresh=()=>{persist();rebuildInputs();update();};
 $('#asset-add').onclick=()=>{state.assets.push({type:'bonds',name:'Bonds',amount:0,rate:.04});refresh();};
 $$('[data-remove-asset]').forEach(b=>b.onclick=()=>{state.assets.splice(+b.dataset.removeAsset,1);Object.assign(state,assetTotals(state.assets));refresh();});
 state.assets.forEach((a,i)=>{for(const key of ['type','name','amount','rate']){
 const el=$('#asset-'+key+'-'+i);el.oninput=()=>{a[key]=['name','type'].includes(key)?el.value:readNumber(el.value)/(key==='rate'?100:1);Object.assign(state,assetTotals(state.assets));persist();syncSolved();};el.onblur=()=>update();
 }});
 $('#future-add').onclick=()=>{state.futureChanges.push({kind:'income',name:'',amount:0,start:Math.max(0,67-state.age),end:null,adjust:true,enabled:true});refresh();};
 $$('[data-remove-future]').forEach(b=>b.onclick=()=>{state.futureChanges.splice(+b.dataset.removeFuture,1);refresh();});
 state.futureChanges.forEach((e,i)=>{for(const key of ['kind','name','amount','start','end','adjust','enabled']){const el=$('#future-'+key+'-'+i);if(!el)continue;el.oninput=()=>{e[key]=key==='enabled'?el.checked:key==='adjust'?el.value==='yes':['kind','name'].includes(key)?el.value:el.value===''?null:readNumber(el.value)-(['start','end'].includes(key)&&state.timeEntry==='age'?state.age:0);persist();if(key==='name')$('#future-heading-'+i).textContent=e.name.trim()||({income:'Recurring income',add:'One-time addition',expense:'One-time expense'}[e.kind]);if(key==='kind')refresh();};el.onblur=()=>update();}});
}
function renderCoast(){
 const p=baselinePlan(state);$('#error').hidden=true;
 $('#view').innerHTML=`<section class="panel content-panel"><h2>When can your investments grow to FI without further contributions?</h2><p>Cover living costs elsewhere during the coast period. Scheduled future changes still apply.</p>${select('coast-mode','Solve for',{amount:'Coast Fi investment amount',time:'When can I stop contributing?',retirement:'When can I retire without contributing?'},coast.mode)}<div class="two-fields">${coast.mode!=='retirement'?field('coast-years',p.timeEntry==='age'?'Retirement age':'Years until retirement',coast.years+(p.timeEntry==='age'?p.age:0),{min:1,max:p.timeEntry==='age'?p.age+100:100,step:1}):''}${coast.mode==='time'?field('coast-contribution','Annual contributions until coasting',coast.contribution,{prefix:'$',min:0,hint:'Increases with inflation.'}):''}</div>${sharedCards(p,'coast')}</section><section id="coast-results"></section>`;
 bindSharedCards('coast',p);$('#coast-mode').onchange=e=>{coast.mode=e.target.value;persist();renderCoast();};
 for(const key of ['years','contribution']){const el=$('#coast-'+key);if(el)el.oninput=()=>{coast[key]=readNumber(el.value)-(key==='years'&&p.timeEntry==='age'?p.age:0);persist();coastResults(p);};}coastResults(p);
}
function coastResults(p){charts=[];try{
 const solved=solveCoast(p,coast),q=solved.projection,at=coast.mode==='retirement'?solved.value:coast.years;
 const headline=coast.mode==='amount'?money(solved.value)+' invested to coast now':coast.mode==='time'?(solved.value===0?'You can coast now':'Coast in '+num(solved.value,2)+' years · '+dateLabel(solved.value)):'FI in '+num(solved.value,2)+' years · '+dateLabel(solved.value);
 const rows=q.rows.map(r=>({...r,total:displayAmount(r.total,p,r.year),target:displayAmount(r.target,p,r.year)}));
 $('#coast-results').innerHTML=`<h2 class="result-divider">Your Coast Fi results</h2><section class="panel content-panel"><h2>${headline}</h2><p>${coast.mode==='amount'?'Plus your existing cash. Investment allocation stays proportional.':coast.mode==='time'?'Regular contributions stop at the coast date.':'No regular contributions or withdrawals.'} ${p.timeEntry==='age'?'Retirement age: '+num(p.age+at,1)+'.':''}</p>${dollarControls()}${targetCaption(q.target,p,at)}${chart('coast-assets',rows,[{key:'total',label:'Total assets',color:'var(--purple)'},{key:'target',label:'FI target',color:'var(--muted)',dash:true}],{marker:coast.mode==='time'?solved.value:null})}<p class="hint">Constant-return projection, not a probability of success.</p></section>`;
 $('#coast-results').insertAdjacentHTML('beforeend',planTimeline(p,[...(coast.mode==='time'?[{action:'contribute',label:'Contribute',years:solved.value}]:[]),{action:'even',label:'Coast',years:null}],q.rows.at(-1).year,q.reached)+fundingChart(p,q.rows,nominal));
 $$('[data-dollars]').forEach(b=>b.onclick=()=>{nominal=b.dataset.dollars==='nominal';persist();coastResults(p);});drawCharts();
 }catch(e){$('#coast-results').innerHTML='<section class="panel content-panel" role="alert"></section>';$('#coast-results section').textContent=e.message;}}

function freshComparison(){
 let p=compareSource==='plan'?structuredClone(state):structuredClone(baselinePlan(state));
 if(compareSource==='plan'){try{p=solve(p,unknown).plan||p;}catch{}p=resolveWithdrawals(p);p.nominal=nominalReturn(expectedReturn(p),p.inflation);p.returnMode='nominal';}
 const settings=structuredClone(compareSource==='gap'?gapSettings:compareSource==='coast'?{...coast,coastAt:0}:compareSource==='traditional'?traditional:{});
 let question=compareSource==='plan'?(universalQuestions.plan[unknown]?unknown:'time'):settings.mode||'time';
 return {question,count:3,horizon:Math.max(30,Math.ceil(settings.years||p.years||0)),scenarios:Array.from({length:3},()=>({plan:structuredClone(p),settings:structuredClone(settings),periods:structuredClone(gapPeriods)}))};
}
function renderUniversalComparison(){
 compareDraft??=freshComparison();compareDrafts[compareSource]=compareDraft;const d=compareDraft,source=compareSource,names={plan:'Risk Fi',gap:'Gap Fi',coast:'Coast Fi',traditional:'Traditional Fi'};
 $('#error').hidden=true;
 const input=(i,path,label,value,opts={})=>field('uc-'+i+'-'+path,label,value,opts);
 const cards=d.scenarios.slice(0,d.count).map((c,i)=>{const p=c.plan,t=c.settings,q=d.question,age=p.timeEntry==='age';return `<section class="summary-group"><h3>Scenario ${String.fromCharCode(65+i)}</h3>
 ${input(i,'plan.nominal','Return before inflation',entry(p.nominal,100),{suffix:'%',disabled:source==='plan'&&q==='return'})}
 ${source==='plan'?(p.withdrawalMode==='dollars'?input(i,'plan.spending','Annual withdrawals',p.spending,{prefix:'$',disabled:q==='spending'}):input(i,'plan.withdrawalRate',p.withdrawalMode==='annual'?'Each year’s investment withdrawal rate':'Starting investment withdrawal rate',entry(p.withdrawalRate,100),{suffix:'%',disabled:q==='spending'}))+input(i,'plan.portfolio','Starting investments',p.portfolio,{prefix:'$',disabled:q==='portfolio'})+input(i,'plan.years',age?'Target FI age':'Years to FI',p.years+(age?p.age:0),{disabled:q==='time'}):''}
 ${source==='traditional'?input(i,'settings.contribution','Annual contributions',t.contribution,{prefix:'$',disabled:q==='contribution'})+(q==='contribution'?input(i,'settings.years',age?'Target FI age':'Years to FI',t.years+(age?p.age:0),{min:1,step:1}):''):''}
 ${source==='coast'?(q!=='retirement'&&q!=='arrival'?input(i,'settings.years',age?'Retirement age':'Years until retirement',t.years+(age?p.age:0),{min:1,step:1}):'')+(['time','arrival'].includes(q)?input(i,'settings.contribution','Annual contributions',t.contribution,{prefix:'$'}):'')+(q==='arrival'?input(i,'settings.coastAt',age?'Stop contributions at age':'Stop contributions in years',(t.coastAt||0)+(age?p.age:0),{min:0}):''):''}
 ${source==='gap'?(q!=='time'?input(i,'settings.years',age?'Target FI age':'Years to FI',t.years+(age?p.age:0),{min:1,step:1})+select('uc-'+i+'-period','Solve amount in period',Object.fromEntries(c.periods.map((r,j)=>[j,r]).filter(([,r])=>r.action===q).map(([j])=>[j,'Period '+(j+1)])),t.index):'')+c.periods.map((r,j)=>`<div class="compare-period"><h4>Period ${j+1} · ${{withdraw:'Withdraw',contribute:'Contribute',even:'Break even'}[r.action]}</h4>${r.action!=='even'?input(i,'periods.'+j+'.amount','Annual amount',r.amount,{prefix:'$',disabled:q===r.action&&t.index===j}):''}${r.years===null?'<p class="hint">Until FI</p>':input(i,'periods.'+j+'.years','Years',r.years,{min:1,max:99,step:1})}</div>`).join(''):''}
 </section>`;}).join('');
 $('#view').innerHTML=`<section class="panel content-panel"><h2>${names[source]} · Compare scenarios</h2><p>Scenarios are copies of your calculator inputs. Temporary edits stay here. Reset to load updated calculator inputs.</p>${select('uc-question','Solve for',universalQuestions[source],d.question)}${select('uc-count','Scenarios',{2:'Two',3:'Three'},d.count)}<div class="compare-cards">${cards}</div><button id="uc-reset">Reset from current calculator</button><p class="hint">Starting investments: ${money(d.scenarios[0].plan.portfolio)}${source==='plan'?' (editable above)':''}. Shared: ${money(d.scenarios[0].plan.cash)} cash, ${money(fiTarget(d.scenarios[0].plan))} FI target in today’s dollars, ${percent(d.scenarios[0].plan.inflation)} inflation, and your future changes. ${source==='plan'?'Your withdrawal basis and inflation setting stay fixed. Calculated withdrawal amounts show the first year’s dollars.':''} Return edits shift your investment asset returns together.</p></section><h2 class="result-divider">Comparison results</h2><section class="panel content-panel">${dollarControls()}${field('uc-horizon','Years to show',d.horizon,{min:1,max:100,step:1})}<div id="uc-results"></div></section>`;
 $('#uc-question').onchange=e=>{d.question=e.target.value;if(source==='gap'&&d.question!=='time')d.scenarios.forEach(c=>c.settings.index=c.periods.findIndex(r=>r.action===d.question));renderUniversalComparison();};
 $('#uc-count').onchange=e=>{d.count=+e.target.value;renderUniversalComparison();};
 $('#uc-reset').onclick=()=>{compareDraft=null;renderUniversalComparison();};
 $$('[id^="uc-"]').filter(el=>el.tagName==='INPUT'&&el.id!=='uc-horizon').forEach(el=>el.oninput=()=>{const [,i,path]=el.id.split('-'),c=d.scenarios[+i],keys=path.split('.');let value=readNumber(el.value);if(value!==null){if(['plan.nominal','plan.withdrawalRate'].includes(path))value/=100;if(['plan.years','settings.years','settings.coastAt'].includes(path)&&c.plan.timeEntry==='age')value-=c.plan.age;}let obj=c;for(const key of keys.slice(0,-1))obj=obj[key];obj[keys.at(-1)]=value;universalResults();});
 d.scenarios.forEach((c,i)=>{const el=$('#uc-'+i+'-period');if(el)el.onchange=()=>{c.settings.index=+el.value;renderUniversalComparison();};});
 $('#uc-horizon').oninput=e=>{d.horizon=readNumber(e.target.value);universalResults();};
 $$('[data-dollars]').forEach(b=>b.onclick=()=>{nominal=b.dataset.dollars==='nominal';persist();renderUniversalComparison();});universalResults();
}
function universalResults(){
 charts=[];const d=compareDraft;const results=d.scenarios.slice(0,d.count).map(c=>runScenario(compareSource,d.question,c,d.horizon));
 const value=r=>r.kind==='time'?(r.plan.timeEntry==='age'?'Age '+num(r.plan.age+r.value,2):num(r.value,2)+' years')+' · '+dateLabel(r.value):r.kind==='realReturn'?percent(nominalReturn(r.value,r.plan.inflation))+' before inflation':money(r.value)+' in today’s dollars';
 const valid=results.some(r=>!r.error),rows=valid?comparisonRows(results,d.horizon,nominal):[];
 $('#uc-results').innerHTML=`<div class="compare-cards">${results.map((r,i)=>`<section class="metric"><h3>Scenario ${String.fromCharCode(65+i)}</h3>${r.error?`<p>${safeText(r.error)}</p>`:`<strong class="value">${value(r)}</strong>${(r.projection.unfunded>0.01||r.projection.shortfall!=null)?'<p class="notice">A funding shortfall occurs within the chart horizon.</p>':''}`}</section>`).join('')}</div>${valid?chart('scenario-comparison',rows,[...results.flatMap((r,i)=>r.error?[]:[{key:'s'+i,label:'Scenario '+String.fromCharCode(65+i),color:['var(--purple)','var(--red)','#438b85'][i]}]),{key:'target',label:'FI target',color:'var(--muted)',dash:true}]):''}<p class="chart-caption">Same question and starting assumptions; only the entries above differ. Constant-return projections, not probabilities. The chart keeps each scenario’s rules through the displayed horizon; no automatic retirement withdrawal switch. Missing or unfunded projections are not shown as successful plans.</p>`;drawCharts();
}

function pathDefaults(){
 let r=state;try{r=solve(state,unknown).plan||state;}catch{}
 let coastAt=0;try{if(coast.mode==='time')coastAt=solveCoast(baselinePlan(state),coast).value;}catch{}
 let tr={...traditional},periods=structuredClone(gapPeriods);
 try{if(tr.mode==='contribution')tr.contribution=contributionNeeded(baselinePlan(state),tr).contribution;}catch{}
 try{if(gapSettings.mode!=='time')periods[gapSettings.index].amount=solveGapAmount({...baselinePlan(state),...gapSettings,adjustWithdrawals:gapSettings.adjust},periods,gapSettings).amount;}catch{}
 return {risk:{spending:r.spending,withdrawalMode:r.withdrawalMode,withdrawalRate:r.withdrawalRate,adjustWithdrawals:r.adjustWithdrawals,cashStrategy:r.cashStrategy,cashMinimum:r.cashMinimum},gap:structuredClone(gapSettings),periods,coast:{contribution:coast.contribution,coastAt},traditional:tr};
}
function renderPathComparison(){
 pathDraft??=pathDefaults();const d=pathDraft,p=baselinePlan(state),age=state.timeEntry==='age';$('#error').hidden=true;
 const f=(path,label,value,opts={})=>field('path-'+path,label,value,opts);
 const cards={plan:`<section class="summary-group"><h3>Risk Fi</h3>${d.risk.withdrawalMode==='dollars'?f('risk.spending','Annual withdrawals',d.risk.spending,{prefix:'$'}):f('risk.withdrawalRate',d.risk.withdrawalMode==='annual'?'Each year’s investment withdrawal rate':'Starting investment withdrawal rate',entry(d.risk.withdrawalRate,100),{suffix:'%'})}<p class="hint">Uses the Risk Fi withdrawal and cash rules.</p></section>`,gap:`<section class="summary-group"><h3>Gap Fi</h3>${d.periods.map((r,i)=>`<div class="compare-period"><h4>Period ${i+1} · ${{withdraw:'Withdraw',contribute:'Contribute',even:'Break even'}[r.action]}</h4>${r.action!=='even'?f('periods.'+i+'.amount','Annual amount',r.amount,{prefix:'$'}):''}${r.years===null?'<p>Until FI</p>':f('periods.'+i+'.years','Years',r.years,{min:1,step:1})}</div>`).join('')}</section>`,coast:`<section class="summary-group"><h3>Coast Fi</h3>${f('coast.contribution','Annual contributions before coasting',d.coast.contribution,{prefix:'$'})}${f('coast.coastAt',age?'Stop contributions at age':'Stop contributions in years',d.coast.coastAt+(age?state.age:0),{min:0})}<p class="hint">No regular withdrawals. Contributions rise with inflation and stop at the coast date.</p></section>`,traditional:`<section class="summary-group"><h3>Traditional Fi</h3>${f('traditional.contribution','Annual contributions',d.traditional.contribution,{prefix:'$'})}<p class="hint">${d.traditional.adjust?'Contributions rise with inflation.':'Contributions stay fixed in future dollars.'}</p></section>`};
 $('#view').innerHTML=`<section class="panel content-panel"><h2>Which path gets you to FI?</h2><p>Same starting assets, returns, inflation, future changes and FI target. Compare the withdrawals and contributions along each path.</p><div class="metrics">${metric('Starting assets',money(p.portfolio+p.cash))}${metric('FI target · today',money(fiTarget(p)))}${metric('Investment return / inflation',percent(p.nominal)+' / '+percent(p.inflation))}</div><div class="path-cards">
${pathSelection.map((key,i)=>`<div><label for="path-choice-${i}">Path ${i+1}</label><select id="path-choice-${i}" data-path-choice="${i}">${Object.entries(pathNames).map(([k,name])=>`<option value="${k}" ${k===key?'selected':''} ${k===pathSelection[1-i]?'disabled':''}>${name}</option>`).join('')}</select>${cards[key]}</div>`).join('')}</div><button id="paths-reset">Reset rules from calculators</button><p class="hint">Rule edits here are temporary. Your shared numbers remain connected. Change period types or withdrawal policies in their calculator, then reset here.</p></section><h2 class="result-divider">Path comparison results</h2><section class="panel content-panel">${dollarControls()}${f('horizon','Years to show',pathHorizon,{min:1,max:100,step:1})}<div id="paths-results"></div></section>`;
 $$('[data-path-choice]').forEach(el=>el.onchange=()=>{pathSelection[Number(el.dataset.pathChoice)]=el.value;renderPathComparison();});
 $('#paths-reset').onclick=()=>{pathDraft=null;renderPathComparison();};
 $$('input[id^="path-"]').forEach(el=>el.oninput=()=>{const path=el.id.slice(5),keys=path.split('.');let value=readNumber(el.value);if(path==='horizon')pathHorizon=value;else{if(value!==null){if(path==='risk.withdrawalRate')value/=100;if(path==='coast.coastAt'&&age)value-=state.age;}let obj=d;for(const k of keys.slice(0,-1))obj=obj[k];obj[keys.at(-1)]=value;}pathResults();});
 $$('[data-dollars]').forEach(b=>b.onclick=()=>{nominal=b.dataset.dollars==='nominal';persist();renderPathComparison();});pathResults();
}
function pathResults(){
 charts=[];const host=$('#paths-results');try{
 const r=comparePaths(state,pathDraft,pathHorizon,pathSelection),names=pathSelection.map(key=>pathNames[key]),colours=['var(--purple)','var(--red)'];
 host.innerHTML=`<div class="table-scroll"><table><thead><tr><th>Path</th><th>FI date / age</th><th>Regular contributions to FI</th><th>Portfolio withdrawals to FI</th></tr></thead><tbody>${r.map((v,i)=>`<tr><th>${names[i]}</th>${v.error?`<td colspan="3">${safeText(v.error)}</td>`:`<td>${dateLabel(v.value)} · ${state.timeEntry==='age'?'Age '+num(state.age+v.value,2):num(v.value,2)+' years'}</td><td>${money(v.contributions)}</td><td>${money(v.withdrawals)}</td>`}</tr>`).join('')}</tbody></table></div><p class="hint">Totals through each path’s own FI date, in today’s dollars. Regular contributions exclude future-income surpluses and one-time additions; these still affect balances. Portfolio withdrawals include one-time expenses.</p>${r.some(v=>!v.error)?chart('paths-assets',comparisonRows(r,pathHorizon,nominal),[...r.flatMap((v,i)=>v.error?[]:[{key:'s'+i,label:names[i],color:colours[i]}]),{key:'target',label:'FI target',color:'var(--muted)',dash:true}]):''}<p class="chart-caption">${nominal?'Future':'Today’s'} dollars. Constant-return projections, not success probabilities. Risk Fi uses annual cash flows; the other paths use monthly cash flows. The chart continues each path’s rules after FI for comparison; it does not switch to retirement withdrawals.</p>`;drawCharts();
 }catch(e){host.textContent=e.message;}
}
